Player class:
```js
class Player {
  constructor(){
    this.x = W/2; this.y = H/2;
    this.vx=0; this.vy=0;
    this.radius = 40;
    this.maxHealth = 100; this.health = 100;
    this.score = 0;
    this.tentacles = 8;
    this.angle = 0; // facing angle
    this.hurtTimer = 0;
    this.eatCooldown = 0;
    this.speed = 4.5;
  }
  update(input, dt){
    let ax=0, ay=0;
    if(input.left) ax=-1; if(input.right) ax=1;
    if(input.up) ay=-1; if(input.down) ay=1;
    const len = Math.hypot(ax,ay);
    if(len>0){ ax/=len; ay/=len; }
    this.vx += ax*0.6; this.vy += ay*0.6;
    this.vx *= 0.88; this.vy *= 0.88;
    this.x += this.vx; this.y += this.vy;
    // clamp to world? wrap or clamp. Let's clamp with margin so player stays in view.
    this.x = Math.max(this.radius, Math.min(W-this.radius, this.x));
    this.y = Math.max(this.radius, Math.min(H-this.radius, this.y));
    if(Math.abs(this.vx)>0.1 || Math.abs(this.vy)>0.1) this.angle = Math.atan2(this.vy, this.vx);
    if(this.hurtTimer>0) this.hurtTimer -= dt;
    if(this.eatCooldown>0) this.eatCooldown -= dt;
  }
}
```

