```js
drawTentacle(ctx, baseX, baseY, angle, length, time, index){
  const segments = 12;
  const wave = Math.sin(time*0.005 + index*0.8) * 0.4;
  // direction perpendicular-ish
  ctx.beginPath();
  ctx.moveTo(baseX, baseY);
  let cx = baseX, cy = baseY;
  let dir = angle;
  const curl = Math.sin(time*0.003 + index) * 0.5;
  for(let s=1; s<=segments; s++){
    const t = s/segments;
    const segAngle = dir + Math.sin(time*0.004 + index + t*3) * 0.7 + curl*t;
    const step = length/segments;
    const nx = cx + Math.cos(segAngle)*step;
    const ny = cy + Math.sin(segAngle)*step;
    ctx.lineTo(nx, ny);
    cx=nx; cy=ny;
  }
  const thickness = Math.max(2, 8*(1-s/1)); // hmm need per segment
}
```

