function drawWater(){
  const t = Date.now()*0.001;
  ctx.lineWidth=2;
  for(let i=0;i<3;i++){
    const color = i===0 ? 'rgba(20,60,100,0.5)' : 'rgba(30,90,140,0.3)';
    ctx.strokeStyle=color; ctx.beginPath();
    for(let x=0;x<=W;x+=40){
      const y = H*0.55 + Math.sin(x*0.01 + t + i)*20 + i*12;
      if(x===0) ctx.moveTo(x,y); else ctx.lineTo(x,y);
    }
    ctx.stroke();
  }
}
```

